58	
59	    /**
60	     * Pragmatic check for a syntactically valid email address: a non-empty local
61	     * part, a single '@', and a domain with at least one dot-separated label.
62	     */
63	    private static final Pattern EMAIL_PATTERN =
64	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
65	
66	    private final ClinicService clinicService;
