109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        // Validate & normalize the optional email; reject the create when it is present but invalid.
113	        if (!normalizeEmail(ownerFieldsDto)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
117	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
118	        if (normalizedTelephone == null) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
122	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
123	            .map(Owner::getTelephone)
124	            .map(OwnerRestControllerV1::toE164)
125	            .filter(existing -> existing != null)
126	            .anyMatch(normalizedTelephone::equals);
127	        if (telephoneInUse) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        ownerFieldsDto.setTelephone(normalizedTelephone);
131	        HttpHeaders headers = new HttpHeaders();
132	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
133	        // Default the registration date to the server's current date when none was supplied.
134	        if (owner.getRegistrationDate() == null) {
135	            owner.setRegistrationDate(LocalDate.now());
136	        }
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    /**
145	     * Validate and normalize the optional owner email in place.
146	     *
147	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
148	     * When present it must be a syntactically valid address; a valid address is
149	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
150	     * present but syntactically invalid, so the caller can reject with 400.
151	     */
152	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
153	        String email = ownerFieldsDto.getEmail();
154	        if (email == null || email.isBlank()) {
155	            ownerFieldsDto.setEmail(null);
156	            return true;
157	        }
158	        String normalized = email.trim().toLowerCase(Locale.ROOT);
159	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
160	            return false;
161	        }
162	        ownerFieldsDto.setEmail(normalized);
163	        return true;
164	    }
165	
166	    /**
167	     * Normalize a telephone number to E.164 form.
168	     *
169	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
170	     * explicit leading {@code '+'} and country code it is kept; otherwise the
171	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
172	     * dropped from the national digits. The result must contain 8 to 15 digits
173	     * after the {@code '+'}.
174	     *
175	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
176	     *         the input is absent or cannot form a valid E.164 number.
177	     */
178	    private static String toE164(String raw) {
179	        if (raw == null) {
180	            return null;
181	        }
182	        String trimmed = raw.trim();
183	        boolean hasCountryCode = trimmed.startsWith("+");
184	        // Strip spaces, dashes and brackets.
185	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
186	        String digits;
187	        if (hasCountryCode) {
188	            // Keep the explicit country code; drop the leading '+' for validation.
189	            digits = stripped.substring(1);
190	        } else {
191	            // No country code: assume '+61' and drop a single leading '0'.
192	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
193	            digits = "61" + national;
194	        }
195	        if (!digits.matches("\\d{8,15}")) {
196	            return null;
197	        }
198	        return "+" + digits;
199	    }
