214	        }
215	        currentOwner.setAddress(ownerFieldsDto.getAddress());
216	        currentOwner.setCity(ownerFieldsDto.getCity());
217	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
218	        currentOwner.setLastName(ownerFieldsDto.getLastName());
219	        currentOwner.setTelephone(normalizedTelephone);
220	        currentOwner.setEmail(ownerFieldsDto.getEmail());
221	        this.clinicService.saveOwner(currentOwner);
222	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
223	    }
